import re
import unicodedata

# Characters that NFD decomposition does not reduce to plain ASCII.
_TRANSLIT_MAP = {
    'ð': 'd',
    'þ': 't',
    'ß': 'ss',
    'ł': 'l',
    'đ': 'd',
}


def _translit(ch):
    """Reduce a single character to plain ASCII where possible."""
    ch = ch.lower()
    if ch in _TRANSLIT_MAP:
        return _TRANSLIT_MAP[ch]
    decomposed = unicodedata.normalize('NFD', ch)
    base = [c for c in decomposed if not unicodedata.category(c).startswith('M')]
    if base:
        return ''.join(base)
    return ''


def slugify(s):
    out = []
    for ch in s:
        if ch.isalnum():
            out.append(_translit(ch))
        elif ch.isspace() or ch in '-_':
            out.append('-')
    s = ''.join(out)
    s = re.sub(r'-{2,}', '-', s)
    return s.strip('-')

